# GENERATED by tools/build_owui_photo.py. Do not edit; edit the package
# and adapters/openwebui/kitegate_photo.py, then rebuild.


# A real photograph for a child's question, from a named curated source.
#
# The providers, the subject screening and the response parsing all live in
# kitegate.photos, which this file inlines when built — so the same provider
# code is covered by the test suite rather than living only in a pasted
# function. This file is the part that cannot be unit tested: HTTP, throttling
# and the cache.
#
#   python tools/build_owui_photo.py   ->  dist/kitegate_openwebui_photo.py
#
# Install the BUILT file in Admin Panel > Functions > Tools, then enable it on
# the children's model. Open WebUI has no way to install a tool from the
# environment, so this step is manual even in the bundle.
#
# ---------------------------------------------------------------------------
# THIS TOOL DOES NOT MAKE A PICTURE SAFE TO SHOW
# ---------------------------------------------------------------------------
# It chooses a careful SOURCE. Whether the picture is displayed is decided by
# the gateway's image policy (KITEGATE_IMAGE_POLICY, see src/kitegate/images.py),
# which sees the URL on the way back to the child and removes it if it fails a
# moderation check. The two halves are independent on purpose:
#
#   this tool          narrow the source, and screen the subject before the
#                      request leaves, because a tool executes in Open WebUI's
#                      own backend and does not pass through the gateway first
#   the image policy   check the actual picture, and have the final say
#
# If you run the single-file FILTER instead of the gateway, there is no image
# policy and this tool is the only control. Prefer the gateway.
#
# ---------------------------------------------------------------------------
# DEPENDENCIES
# ---------------------------------------------------------------------------
# requests and pydantic only, both already in the open-webui image. There is
# deliberately no requirements frontmatter: a bundle that sets
# ENABLE_PIP_INSTALL_FRONTMATTER_REQUIREMENTS=False would not install a
# declared dependency, so this would fail at call time instead of load time.
#
# ---------------------------------------------------------------------------
# RATE LIMITING
# ---------------------------------------------------------------------------
# Measured against the live MediaWiki API: a single ten-subject run was enough
# to start receiving HTTP 429 when the code issued several requests per
# subject. That mattered more than it looked, because a throttled request
# returned nothing and the caller reported "no photograph found" — identical
# to a subject that genuinely has no image. The tool looked randomly
# unreliable to a child rather than rate-limited to an operator.
#
# Hence: one request per subject in the common case (the provider resolves the
# title and returns the image together), a process-wide minimum gap, one
# bounded retry, an in-process cache, and 429 reported distinctly so it can
# never again be mistaken for a missing picture.
#
# Wikimedia sends no Retry-After or equivalent on a 429 — measured, there is
# nothing in the response to respect — so the only option is a short backoff.
import threading
import time
from typing import Optional, Tuple

import requests
from pydantic import BaseModel, Field

# ---- inlined from src/kitegate/photos.py ----
import re
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple
from urllib.parse import urlsplit, urlunsplit

# ---------------------------------------------------------------------------
# SUBJECT SCREENING, and why it lives here rather than only in the engine
# ---------------------------------------------------------------------------
# A front end executes a tool in its OWN backend. The model's request to call
# the tool passes through the gateway, so the policy does see the arguments on
# the response side, but the EXECUTION and the URL it returns do not pass
# through the gateway before the front end has them. The policy only sees the
# result on the next round trip.
#
# So without a check at this point, the subject string the model invents is the
# one input to the whole feature that reaches an external API unscreened.
#
# This list is about IMAGERY, not about conversation. The topic policy belongs
# to the pack and the engine, and duplicating it here would produce confusing
# double failures. Every pattern is \b-anchored, for the reasons in core.py:
# "Drugstore beetle" and "needlefish" are not drug references.
BLOCKED_SUBJECT = re.compile(
    r"\b(?:"
    r"nude|naked|nudity|porn\w*|sex|sexual|genital\w*|penis|vagina|breasts?|"
    # gor(?:e|y), not a bare "gore": the ported pattern missed "a gory
    # battle", which is exactly the phrasing a child would use. Safe to widen
    # because the \b anchors keep Gregory, allegory and category out — in all
    # three, "gory" is preceded by a word character.
    r"anatomy|autopsy|corpse|cadaver|dead body|gor(?:e|y)|wound|injur\w*|surgery|"
    r"childbirth|birth canal|abortion|"
    r"execution|hanging|lynching|beheading|massacre|atrocity|"
    r"torture|mutilat\w*|suicide|self[- ]harm|"
    r"drugs?\b|syringe|needles?\b|cocaine|heroin|cannabis|"
    r"lingerie|bikini|swimsuit|underwear"
    r")\b",
    re.IGNORECASE,
)

# Deliberately does not name the word that matched. Telling a model exactly
# what tripped a filter invites it to retry around it.
REFUSED_SUBJECT_REPLY = (
    "No picture is available for that subject. Do not try a different wording "
    "for it. Answer in words instead, and if the child asked about something "
    "that is not suitable, suggest they ask a grown-up.")

_TRACKING_PREFIXES = ("utm_",)
MAX_CAPTION = 240


def strip_tracking(url: str) -> str:
    """Drop utm_* parameters.

    Measured: every image URL from the MediaWiki API carries utm_source,
    utm_campaign and utm_content. Removed so a child's browser does not make
    an analytics-tagged request, and so the same picture reached by two routes
    is one cache key in images.py rather than two.
    """
    parts = urlsplit(url)
    if not parts.query:
        return url
    kept = [pair for pair in parts.query.split("&")
            if pair and not pair.split("=", 1)[0].startswith(_TRACKING_PREFIXES)]
    return urlunsplit(parts._replace(query="&".join(kept)))


def shorten(text: str, limit: int = MAX_CAPTION) -> str:
    """The first line of an article intro, trimmed on a word boundary."""
    caption = (text or "").strip().split("\n")[0].strip()
    if len(caption) <= limit:
        return caption
    return caption[:limit - 3].rsplit(" ", 1)[0] + "..."


@dataclass(frozen=True)
class Photo:
    title: str
    image_url: str
    caption: str = ""
    provider: str = ""
    source: str = ""     # the endpoint that answered, for the credit line


@dataclass(frozen=True)
class Request:
    url: str
    params: Dict[str, object]


class PhotoProvider:
    """One curated source of photographs.

    `endpoints` are tried in order and the first picture wins, so put the
    better-written or simpler source first.
    """

    name: str = ""
    endpoints: Tuple[str, ...] = ()
    image_hosts: Tuple[str, ...] = ()
    #: False for a provider that only knows one topic, so callers and docs can
    #: say so. A topical provider answers confidently about everything else,
    #: which is worse than not answering.
    general: bool = True
    topic: str = ""

    def lookup(self, endpoint: str, subject: str, width: int) -> Request:
        raise NotImplementedError

    def read_lookup(self, data: dict, endpoint: str) -> Tuple[Optional[str], Optional[Photo]]:
        """(resolved_title, photo). Either may be None.

        A title with no photo is a real and useful answer: it means the
        subject exists but the page has no lead image, which is the signal to
        try a search rather than to report a failure.
        """
        raise NotImplementedError

    def search(self, endpoint: str, subject: str) -> Optional[Request]:
        """A second request that turns a phrase into a title, or None if the
        provider has no search step."""
        return None

    def read_search(self, data: dict) -> List[str]:
        return []


class Wikimedia(PhotoProvider):
    """Wikipedia article lead images: an editor's choice for the subject.

    Simple English first, because its article text is written for learners
    ("the largest living member of the cat family" rather than "the genus
    Panthera") while carrying the same lead image.

    ONE request in the common case. MediaWiki capitalises the first letter and
    follows redirects itself, so a loose "tiger" resolves to "Tiger" without a
    separate call. That matters: an earlier version of this code issued up to
    six requests per subject and a ten-subject run was enough to earn HTTP 429.
    """

    name = "wikimedia"
    endpoints = ("https://simple.wikipedia.org", "https://en.wikipedia.org")
    # BOTH hosts, measured over ten subjects: scaled thumbnails come from
    # thumb.wikimedia.org (7/10) and unscaled originals from
    # upload.wikimedia.org (3/10). Listing only the obvious one would have
    # silently dropped the tiger.
    image_hosts = ("thumb.wikimedia.org", "upload.wikimedia.org")

    def lookup(self, endpoint: str, subject: str, width: int) -> Request:
        return Request(f"{endpoint}/w/api.php", {
            "action": "query", "prop": "pageimages|extracts", "piprop": "thumbnail",
            "pithumbsize": width, "exintro": 1, "explaintext": 1, "titles": subject,
            "format": "json", "redirects": 1})

    def read_lookup(self, data: dict, endpoint: str) -> Tuple[Optional[str], Optional[Photo]]:
        try:
            pages = data["query"]["pages"]
        except (KeyError, TypeError):
            return None, None
        if not isinstance(pages, dict):
            return None, None
        for page in pages.values():
            if not isinstance(page, dict) or "missing" in page:
                continue
            title = page.get("title")
            if not title:
                continue
            thumb = (page.get("thumbnail") or {}).get("source")
            caption = shorten(page.get("extract") or "")
            if not thumb:
                # A disambiguation page reports no lead image. Measured:
                # "Mercury" comes back with a title, an extract listing the
                # meanings, and no thumbnail. So this is the search signal,
                # not an error.
                return title, None
            return title, Photo(title, strip_tracking(thumb), caption, self.name,
                                urlsplit(endpoint).hostname or endpoint)
        return None, None

    def search(self, endpoint: str, subject: str) -> Optional[Request]:
        return Request(f"{endpoint}/w/api.php", {
            "action": "query", "list": "search", "srsearch": subject,
            "srlimit": 3, "srnamespace": 0, "format": "json"})

    def read_search(self, data: dict) -> List[str]:
        try:
            results = data["query"]["search"]
        except (KeyError, TypeError):
            return []
        return [r["title"] for r in (results or [])
                if isinstance(r, dict) and r.get("title")]


class Nasa(PhotoProvider):
    """NASA's public image library. Public domain, no API key.

    TOPICAL, and that is the whole caveat. Measured: "tiger" returns 69 hits,
    every one of them Enceladus's "tiger stripes". It answers everything, and
    confidently, so it is not a general fallback and is off by default. Enable
    it alongside Wikimedia for a space-heavy deployment, where it is excellent.

    Search is the only step: one request returns the title, a description and
    a preview URL together.
    """

    name = "nasa"
    endpoints = ("https://images-api.nasa.gov",)
    image_hosts = ("images-assets.nasa.gov",)
    general = False
    topic = "space and astronomy"

    def lookup(self, endpoint: str, subject: str, width: int) -> Request:
        return Request(f"{endpoint}/search",
                       {"q": subject, "media_type": "image", "page_size": 5})

    def read_lookup(self, data: dict, endpoint: str) -> Tuple[Optional[str], Optional[Photo]]:
        items = ((data or {}).get("collection") or {}).get("items")
        for item in (items if isinstance(items, list) else []):
            if not isinstance(item, dict):
                continue
            meta = (item.get("data") or [{}])[0]
            if not isinstance(meta, dict):
                continue
            title = meta.get("title")
            # The preview link is used as given rather than rewritten to a
            # larger size. Measured on PIA01518: only ~thumb and ~orig exist,
            # and ~small, ~medium and ~large all return 403. Constructing a
            # size would produce a broken picture most of the time.
            preview = next((l.get("href") for l in item.get("links") or []
                            if isinstance(l, dict) and l.get("rel") == "preview"
                            and l.get("href")), None)
            if not title or not preview:
                continue
            if BLOCKED_SUBJECT.search(title):
                continue
            return title, Photo(title, preview, shorten(meta.get("description") or ""),
                                self.name, urlsplit(endpoint).hostname or endpoint)
        return None, None


PROVIDERS: Dict[str, PhotoProvider] = {p.name: p for p in (Wikimedia(), Nasa())}
DEFAULT_PROVIDERS = ("wikimedia",)


def get_providers(names) -> List[PhotoProvider]:
    """Providers by name, in the order given.

    An unknown name raises rather than being skipped: a typo would otherwise
    read as "pictures are off" and be very hard to tell from a provider
    outage.
    """
    if isinstance(names, str):
        names = [n.strip() for n in names.split(",")]
    wanted = [str(n).strip().lower() for n in (names or []) if str(n).strip()]
    unknown = [n for n in wanted if n not in PROVIDERS]
    if unknown:
        raise ValueError(f"unknown photo provider(s) {unknown}; known: {sorted(PROVIDERS)}")
    return [PROVIDERS[n] for n in wanted or DEFAULT_PROVIDERS]


def image_hosts_for(names) -> List[str]:
    """Every image host the named providers can return.

    Use this to fill KITEGATE_IMAGE_HOSTS, rather than writing the list by
    hand: a provider's hosts are not always the ones you would guess.
    """
    hosts: List[str] = []
    for provider in get_providers(names):
        for host in provider.image_hosts:
            if host not in hosts:
                hosts.append(host)
    return hosts


def next_search_title(titles: List[str], tried: List[str]) -> Optional[str]:
    """The first search result worth a second lookup.

    Skips titles already tried, which the obvious version gets wrong: for
    "Mercury" the search returns ['Mercury', 'Mercury (element)',
    'Mercury (planet)'] and the first result is the disambiguation page that
    just failed. Comparing only against the original subject would retry it
    and give up, so a child asking about Mercury would get no picture at all.

    Also re-checks the title against BLOCKED_SUBJECT: search can land on an
    unsuitable article for an innocent query, so a resolved title is not
    trusted merely because the input passed.
    """
    seen = {t.strip().lower() for t in tried if t}
    for title in titles:
        if not title or title.strip().lower() in seen:
            continue
        if BLOCKED_SUBJECT.search(title):
            continue
        return title
    return None

_MIN_REQUEST_GAP = 1.0   # seconds between outbound calls, process-wide
_RETRY_SLEEP = 2.0       # one backoff before giving up on a 429
_MAX_CACHED = 512
_rate_lock = threading.Lock()
_last_request_at = 0.0


class RateLimited(Exception):
    """A provider returned 429. Distinct from "no image found" on purpose."""


def _throttle() -> None:
    global _last_request_at
    with _rate_lock:
        gap = time.monotonic() - _last_request_at
        if gap < _MIN_REQUEST_GAP:
            time.sleep(_MIN_REQUEST_GAP - gap)
        _last_request_at = time.monotonic()


class Tools:
    class Valves(BaseModel):
        providers: str = Field(
            default="wikimedia",
            description=("Comma-separated photo providers, tried in order: wikimedia "
                         "(Wikipedia lead images), nasa (space only, public domain). "
                         "nasa answers confidently about non-space subjects, so keep it "
                         "after wikimedia."),
        )
        thumb_width: int = Field(default=640, description="Requested image width in pixels.")
        timeout_seconds: int = Field(default=12, description="Per-request HTTP timeout.")
        user_agent: str = Field(
            default="kitegate-photo/1.0 (self-hosted; +https://github.com/kitegate)",
            description=("Sent on every request. Wikimedia asks for a descriptive "
                         "User-Agent and throttles generic ones."),
        )

    def __init__(self) -> None:
        self.valves = self.Valves()
        self._session = requests.Session()
        # (provider, endpoint, subject) -> Photo or None
        self._cache: dict = {}

    # -- internals --------------------------------------------------------
    def _get(self, url: str, params: dict) -> Optional[dict]:
        for attempt in (1, 2):
            _throttle()
            try:
                response = self._session.get(
                    url, params=params or None,
                    headers={"User-Agent": self.valves.user_agent},
                    timeout=self.valves.timeout_seconds)
            except Exception:
                # A network failure reads the same as "no result" to the
                # caller, and a child gains nothing from a stack trace.
                return None
            if response.status_code == 429:
                if attempt == 1:
                    time.sleep(_RETRY_SLEEP)
                    continue
                raise RateLimited(url)
            if response.status_code != 200:
                return None
            try:
                return response.json()
            except ValueError:
                return None
        return None

    def _remember(self, key: tuple, photo: Optional[Photo]) -> None:
        if key in self._cache:
            del self._cache[key]
        elif len(self._cache) >= _MAX_CACHED:
            self._cache.pop(next(iter(self._cache)))
        self._cache[key] = photo

    def _find(self, provider, endpoint: str, subject: str) -> Tuple[Optional[Photo], bool]:
        """(photo, searched). Raises RateLimited."""
        request = provider.lookup(endpoint, subject, self.valves.thumb_width)
        data = self._get(request.url, request.params)
        if data is None:
            return None, False
        title, photo = provider.read_lookup(data, endpoint)
        if photo is not None:
            return photo, False

        # Only now spend a second request: either there is no such article, or
        # it is a disambiguation page, and search is the way through both.
        search = provider.search(endpoint, subject)
        if search is None:
            return None, False
        data = self._get(search.url, search.params)
        if data is None:
            return None, True
        nxt = next_search_title(provider.read_search(data), [subject, title or ""])
        if not nxt:
            return None, True
        request = provider.lookup(endpoint, nxt, self.valves.thumb_width)
        data = self._get(request.url, request.params)
        if data is None:
            return None, True
        _, photo = provider.read_lookup(data, endpoint)
        return photo, True

    # -- tool -------------------------------------------------------------
    def find_photo(self, subject: str) -> str:
        """
        Find one real photograph of a subject, with a short caption.

        Use this when a real picture would help explain something: an animal, a
        planet, a famous building, a country's flag, a historical object. Pass a
        simple noun phrase as the subject, for example "tiger", "Jupiter",
        "Great Pyramid of Giza". Do not pass a whole question.

        Returns markdown containing the image, which you should include in your
        answer. If no suitable photograph is found, say so plainly and carry on
        answering in words.

        :param subject: The thing to find a photograph of, as a short noun phrase.
        """
        subject = (subject or "").strip()
        if not subject:
            return "No subject was given, so no picture was looked up."
        if BLOCKED_SUBJECT.search(subject):
            return REFUSED_SUBJECT_REPLY

        try:
            providers = get_providers(self.valves.providers)
        except ValueError as exc:
            # An operator error, so say so rather than reporting "no picture":
            # a misspelled provider name would otherwise look like an outage.
            return (f"The photo tool is misconfigured and found no provider ({exc}). "
                    "Answer in words instead and tell the child to mention this to a grown-up.")

        throttled = False
        for provider in providers:
            for endpoint in provider.endpoints:
                key = (provider.name, endpoint, subject.lower())
                if key in self._cache:
                    photo = self._cache[key]
                    if photo is not None:
                        return self._render(photo)
                    continue
                try:
                    photo, _ = self._find(provider, endpoint, subject)
                except RateLimited:
                    # Recorded and reported distinctly. Conflating this with
                    # "not found" is the specific bug this branch prevents.
                    throttled = True
                    continue
                self._remember(key, photo)
                if photo is not None:
                    return self._render(photo)

        if throttled:
            return ("The picture library is busy at the moment and would not answer. "
                    "This is nothing to do with what was asked. Answer the question in "
                    "words, and mention that the picture could not be fetched just now "
                    "and is worth trying again shortly.")
        return (f"No photograph was found for '{subject}'. "
                "Answer in words instead, and do not link to any other website.")

    @staticmethod
    def _render(photo: Photo) -> str:
        return (f"Photograph found for '{photo.title}' (from {photo.source}).\n\n"
                f"![{photo.title}]({photo.image_url})\n\n"
                f"{photo.caption}\n\n"
                "Include the image markdown above in your answer, and describe the "
                "picture to the child in your own simple words.")
